#!/usr/bin/env bash
set -Eeuo pipefail

VERSION='NOVA-HYBRID-DISCOVERY-V4-MARKET-WIDE-4.0.0'
EXPECTED_DOCKERFILE_SHA='5fcbb26aafbd75e8ffa828a201047178be343f115d53c5a276c00e18f9944dcb'
STAMP="$(date -u +%Y%m%d-%H%M%S)"
IMAGE="quant-nova:v4-marketwide-${STAMP}"
TMPDIR_V4="$(mktemp -d /tmp/nova-v4-deploy.XXXXXX)"
DF="$TMPDIR_V4/Dockerfile"
CANARY="nova-v4-canary-${STAMP}"
CURRENT=''
BACKUP=''
CUTOVER=0

say() { printf '\n%s\n' "$*"; }
exists() { docker container inspect "$1" >/dev/null 2>&1; }
cleanup() {
  exists "$CANARY" && docker rm -f "$CANARY" >/dev/null 2>&1 || true
  rm -rf "$TMPDIR_V4" >/dev/null 2>&1 || true
}
rollback() {
  set +e
  say 'AUTO_ROLLBACK=START'
  if [ -n "${CURRENT:-}" ] && exists "$CURRENT"; then docker rm -f "$CURRENT" >/dev/null 2>&1 || true; fi
  if [ -n "${BACKUP:-}" ] && exists "$BACKUP"; then
    docker rename "$BACKUP" "$CURRENT" >/dev/null 2>&1 || true
    docker start "$CURRENT" >/dev/null 2>&1 || true
    say 'AUTO_ROLLBACK=SUCCESS'
  else
    say 'AUTO_ROLLBACK=BACKUP_NOT_FOUND'
  fi
}
trap 'rc=$?; if [ "$CUTOVER" = 1 ]; then rollback; fi; cleanup; exit $rc' ERR
trap cleanup EXIT

say '===== NOVA V4 TRUE MARKET-WIDE ONE-FILE DEPLOY ====='

