bmZvIiwiLS1hY2Nlc3MtbG9nIl0K
PAYLOAD
python3 - "$TMPDIR_V4/dockerfile.b64" "$DF" <<'PYDF'
import base64,hashlib,pathlib,sys
src,out=map(pathlib.Path,sys.argv[1:])
raw=base64.b64decode(src.read_text().replace('\n',''),validate=True)
out.write_bytes(raw)
print('DOCKERFILE_BYTES='+str(len(raw)))
print('DOCKERFILE_SHA256='+hashlib.sha256(raw).hexdigest())
PYDF
ACTUAL="$(sha256sum "$DF" | awk '{print $1}')"
[ "$ACTUAL" = "$EXPECTED_DOCKERFILE_SHA" ] || { echo "SELFTEST_FAIL expected=$EXPECTED_DOCKERFILE_SHA actual=$ACTUAL"; exit 10; }
echo 'EMBEDDED_DOCKERFILE_SELFTEST=PASS'

if [ "${NOVA_DEPLOY_SELFTEST_ONLY:-0}" = 1 ]; then
  echo "VERSION=$VERSION"
  echo "SHA256=$ACTUAL"
  echo 'RESULT=SELFTEST_ONLY_PASS'
  exit 0
fi

command -v docker >/dev/null 2>&1 || { echo 'ERROR=docker_not_found'; exit 11; }
command -v python3 >/dev/null 2>&1 || { echo 'ERROR=python3_not_found'; exit 12; }
docker info >/dev/null 2>&1 || { echo 'ERROR=docker_daemon_unavailable'; exit 13; }

say '[1/8] Current NOVA container discovery'
for preferred in kiwoom-smartmoney quant-nova; do
  if exists "$preferred" && [ "$(docker inspect -f '{{.State.Running}}' "$preferred" 2>/dev/null)" = true ]; then CURRENT="$preferred"; break; fi
done
if [ -z "$CURRENT" ]; then
  for c in $(docker ps --format '{{.Names}}'); do
    if docker exec "$c" python - <<'PYC' >/dev/null 2>&1
import json,urllib.request,sys
try:
 j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/livez',timeout=2));sys.exit(0 if j.get('ok') else 1)
except Exception:sys.exit(1)
PYC
    then CURRENT="$c"; break; fi
  done
fi
[ -n "$CURRENT" ] || { docker ps; echo 'ERROR=current_nova_not_found'; exit 14; }
BACKUP="${CURRENT}-backup-pre-v4-${STAMP}"
echo "CURRENT=$CURRENT"

say '[2/8] Preserve runtime contract'
docker inspect "$CURRENT" > "$TMPDIR_V4/current.json"
mapfile -d '' -t PROD_ARGS < <(python3 - "$TMPDIR_V4/current.json" <<'PYARGS'
import json,sys
j=json.load(open(sys.argv[1]))[0];c=j.get('Config') or {};h=j.get('HostConfig') or {};args=[]
for e in c.get('Env') or []: args += ['--env',e]
seen=set()
for b in h.get('Binds') or []:
 args += ['--volume',b]
 p=b.split(':')
 if len(p)>1: seen.add(p[1])
for m in j.get('Mounts') or []:
 t=m.get('Destination') or ''
 if not t or t in seen: continue
 typ=m.get('Type') or 'volume';src=m.get('Name') or m.get('Source') or ''
 spec=[f'type={typ}']
 if src: spec.append(f'source={src}')
 spec.append(f'target={t}')
 if not m.get('RW',True):spec.append('readonly')
 args += ['--mount',','.join(spec)]
for t,opt in (h.get('Tmpfs') or {}).items():args += ['--tmpfs',t+(':'+opt if opt else '')]
for private,bindings in (h.get('PortBindings') or {}).items():
 for b in bindings or []:
  hp=(b.get('HostPort') or '').strip();hi=(b.get('HostIp') or '').strip()
  if hp:args += ['--publish',(hi+':' if hi else '')+hp+':'+private]
net=h.get('NetworkMode') or ''
if net and net not in ('default','bridge'):args += ['--network',net]
rp=h.get('RestartPolicy') or {};rn=rp.get('Name') or ''
if rn:
 cnt=int(rp.get('MaximumRetryCount') or 0);val=rn+(':'+str(cnt) if rn=='on-failure' and cnt else '')
 args += ['--restart',val]
mem=int(h.get('Memory') or 0)
if mem>0:args += ['--memory',str(mem)]
ncpu=int(h.get('NanoCpus') or 0)
if ncpu>0:args += ['--cpus',str(ncpu/1_000_000_000)]
for a in args:sys.stdout.buffer.write(str(a).encode()+b'\0')
PYARGS
)

say '[3/8] Build image — embedded source tests are build gates'
DOCKER_BUILDKIT=1 docker build --no-cache -f "$DF" -t "$IMAGE" "$TMPDIR_V4"

say '[4/8] Image contract check'
getlabel() { docker image inspect --format "{{index .Config.Labels \"$1\"}}" "$IMAGE"; }
[ "$(getlabel org.opencontainers.image.version)" = "$VERSION" ] || { echo 'ERROR=image_version'; exit 20; }
[ "$(getlabel io.quantnova.hybrid_discovery_v4)" = 'TRUE_MARKET_WIDE_FULL_CUTOVER' ] || { echo 'ERROR=v4_label'; exit 21; }
[ "$(getlabel io.quantnova.hybrid_v3_ws_types_added)" = '0' ] || { echo 'ERROR=ws_type_contract'; exit 22; }
[ "$(getlabel io.quantnova.anchor_entitlement)" = 'NONE_DISCOVERY_RANK' ] || { echo 'ERROR=anchor_contract'; exit 23; }
echo 'IMAGE_CONTRACT=PASS'

say '[5/8] Offline canary — no live broker traffic'
docker run -d --name "$CANARY" --network none \
  --env NOVA_DATA_DIR=/tmp/nova-v4-canary \
  --env NOVA_LEGACY_DATA_DIR=/tmp/nova-v4-canary-legacy \
  "$IMAGE" >/dev/null
CANARY_OK=0
for _ in $(seq 1 45); do
 if docker exec "$CANARY" python - "$VERSION" <<'PYCAN' >/dev/null 2>&1
import json,sys,urllib.request
v=sys.argv[1]
def g(p):return json.load(urllib.request.urlopen('http://127.0.0.1:8000'+p,timeout=3))
try:
 assert g('/api/livez').get('ok') is True
 assert g('/api/version').get('version')==v
 h=g('/api/hybrid-discovery-v4')
 assert h.get('engine')=='HYBRID_DISCOVERY_V4_MARKET_WIDE'
 assert h.get('broker_calls_added')==2 and h.get('ws_types_added')==0
 sys.exit(0)
except Exception:sys.exit(1)
PYCAN
 then CANARY_OK=1;break;fi
 sleep 2
done
[ "$CANARY_OK" = 1 ] || { docker logs --tail 160 "$CANARY" || true; echo 'ERROR=offline_canary'; exit 24; }
docker rm -f "$CANARY" >/dev/null
echo 'OFFLINE_CANARY=PASS'

say '[6/8] Safe cutover'
CUTOVER=1
docker rename "$CURRENT" "$BACKUP"
docker stop "$BACKUP" >/dev/null
if ! docker run -d --name "$CURRENT" "${PROD_ARGS[@]}" "$IMAGE" >/dev/null; then
 echo 'ERROR=new_container_start'; rollback; CUTOVER=0; exit 30
fi

say '[7/8] Runtime health + true master verification'
RUNTIME_OK=0
for _ in $(seq 1 75); do
 if docker exec "$CURRENT" python - "$VERSION" <<'PYRUN' >/dev/null 2>&1
import json,sys,urllib.request
v=sys.argv[1]
def g(p):return json.load(urllib.request.urlopen('http://127.0.0.1:8000'+p,timeout=4))
try:
 assert g('/api/livez').get('ok') is True
 assert g('/api/version').get('version')==v
 h=g('/api/hybrid-discovery-v4')
 assert h.get('engine')=='HYBRID_DISCOVERY_V4_MARKET_WIDE'
 m=h.get('metrics') or {}
 assert int(m.get('master_count') or 0)>=500
 sys.exit(0)
except Exception:sys.exit(1)
PYRUN
 then RUNTIME_OK=1;break;fi
 sleep 2
done
if [ "$RUNTIME_OK" != 1 ]; then
 docker logs --tail 220 "$CURRENT" || true
 echo 'ERROR=runtime_master_not_verified'; rollback; CUTOVER=0; exit 31
fi

ACTIVE_CHECK="$(python3 - <<'PYTIME'
from datetime import datetime,time
from zoneinfo import ZoneInfo
n=datetime.now(ZoneInfo('Asia/Seoul'));t=n.time();wd=n.weekday()<5
active=wd and ((time(9,5)<=t<=time(15,25)) or (time(15,40)<=t<=time(19,50)))
print('1' if active else '0')
PYTIME
)"
if [ "$ACTIVE_CHECK" = 1 ]; then
 SNAP_OK=0
 for _ in $(seq 1 90); do
  if docker exec "$CURRENT" python - <<'PYSNAP' >/dev/null 2>&1
import json,urllib.request,sys
try:
 h=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/hybrid-discovery-v4',timeout=4));m=h.get('metrics') or {}
 assert float(m.get('last_scan_at') or 0)>0
 assert int(m.get('candidate60_count') or 0)>0
 sys.exit(0)
except Exception:sys.exit(1)
PYSNAP
  then SNAP_OK=1;break;fi
  sleep 2
 done
 if [ "$SNAP_OK" != 1 ]; then docker logs --tail 220 "$CURRENT" || true;echo 'ERROR=active_session_ka10095_scan_not_verified';rollback;CUTOVER=0;exit 32;fi
 echo 'ACTIVE_SESSION_BATCH_SNAPSHOT=PASS'
else
 echo 'ACTIVE_SESSION_BATCH_SNAPSHOT=DEFERRED_MARKET_CLOSED'
fi

CUTOVER=0
say '[8/8] SUCCESS'
echo "RESULT=SUCCESS"
echo "VERSION=$VERSION"
echo "CURRENT=$CURRENT"
echo "BACKUP=$BACKUP"
echo "IMAGE=$IMAGE"
echo "EMBEDDED_DOCKERFILE_SHA256=$ACTUAL"
docker ps --filter "name=$CURRENT" --format 'table {{.Names}}\t{{.Image}}\t{{.Status}}\t{{.Ports}}'
